  ('t1-r1-31', 't1-r1', 31, 'topic', null, '저는 한국 사람입니다. 친구는 일본 사람입니다.', null, '["나이","직업","이름","나라"]'::jsonb, 4, '한국 사람 / 일본 사람 → countries.', null, null, null),
