  ('t1-r1-38', 't1-r1', 38, 'blank', null, '방이 (    ). 그래서 청소를 합니다.', null, '["따뜻합니다","조용합니다","넓습니다","더럽습니다"]'::jsonb, 4, 'The room is dirty, so I clean it.', null, null, null),
